// Model of Python-Markdown core, restricted to: empty blocks, indented code, paragraphs.
const PY_SPACE = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,0x1680,
  0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200a,
  0x2028,0x2029,0x202f,0x205f,0x3000]);
const isPySpace = (ch) => PY_SPACE.has(ch.codePointAt(0));
export function pyRstrip(s){ let i=s.length; while(i>0){ const c=s[i-1]; if(isPySpace(c)) i--; else break; } return s.slice(0,i); }
export function pyLstrip(s){ let i=0; while(i<s.length && isPySpace(s[i])) i++; return s.slice(i); }
export function pyStrip(s){ return pyLstrip(pyRstrip(s)); }

export function expandTabs(s, n=4){
  let out='', col=0;
  for (const ch of s){            // iterates by code point (matches Python chars)
    if (ch==='\n'||ch==='\r'){ out+=ch; col=0; }
    else if (ch==='\t'){ const pad=n-(col%n); out+=' '.repeat(pad); col+=pad; }
    else { out+=ch; col++; }
  }
  return out;
}

export function normalizeWhitespace(src){
  let t = src.split('').join('').split('').join('');
  t = t.split('\r\n').join('\n').split('\r').join('\n') + '\n\n';
  t = expandTabs(t, 4);
  // re.sub(r'(?<=\n) +\n', '\n', t): blank-out space-only lines except the very first line
  const lines = t.split('\n');
  for (let i=1;i<lines.length;i++){
    const L=lines[i];
    if (L.length && i<lines.length-1){
      let allSp=true; for(const c of L) if(c!==' '){allSp=false;break;}
      if(allSp) lines[i]='';
    }
  }
  return lines.join('\n');
}

export function codeEscape(s){
  return s.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;');
}

function detab(text, length=4){
  const lines = text.split('\n');
  const kept=[];
  for (const line of lines){
    if (line.startsWith(' '.repeat(length))) kept.push(line.slice(length));
    else if (pyStrip(line)==='') kept.push('');
    else break;
  }
  return [kept.join('\n'), lines.slice(kept.length).join('\n')];
}

// minimal tree
const el=(tag)=>({tag, text:'', children:[]});

function processBlocks(parent, blocks){
  while (blocks.length){
    const block = blocks[0];
    if (block==='' || block.startsWith('\n')) { emptyProc(parent, blocks); }
    else if (block.startsWith('    ')) { codeProc(parent, blocks); }
    else { paraProc(parent, blocks); }
  }
}
function lastCode(parent){
  const last = parent.children[parent.children.length-1];
  if (last && last.tag==='pre' && last.children.length && last.children[0].tag==='code') return last.children[0];
  return null;
}
function emptyProc(parent, blocks){
  const block = blocks.shift();
  let filler='\n\n';
  if (block){ filler='\n'; const rest=block.slice(1); if(rest) blocks.unshift(rest); }
  const code = lastCode(parent);
  if (code) code.text = code.text + filler;
}
function codeProc(parent, blocks){
  const block = blocks.shift();
  const [detabbed, rest] = detab(block);
  const code = lastCode(parent);
  if (code) code.text = code.text + '\n' + codeEscape(pyRstrip(detabbed)) + '\n';
  else {
    const pre=el('pre'); const c=el('code');
    c.text = codeEscape(pyRstrip(detabbed)) + '\n';
    pre.children.push(c); parent.children.push(pre);
  }
  if (rest) blocks.unshift(rest);
}
function paraProc(parent, blocks){
  const block = blocks.shift();
  if (pyStrip(block)!==''){
    const p=el('p'); p.text=pyLstrip(block); parent.children.push(p);
  }
}
function prettifyPre(root){
  for (const ch of root.children){
    if (ch.tag==='pre' && ch.children.length && ch.children[0].tag==='code'){
      const c=ch.children[0]; c.text = pyRstrip(c.text)+'\n';
    }
  }
}
function esc(s){ return s.split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function render(root){
  let out='';
  for (const ch of root.children){
    if (ch.tag==='pre') out += '<pre><code>'+ch.children[0].text+'</code></pre>'+'\n';
    else out += '<p>'+esc(ch.text)+'</p>'+'\n';
  }
  return pyStrip(out);
}

export function convert(src){
  if (pyStrip(src)==='') return '';
  const t = normalizeWhitespace(src);
  const root = el('div');
  processBlocks(root, t.split('\n\n'));
  prettifyPre(root);
  return render(root);
}

import { spawnSync } from 'node:child_process';
import { writeFileSync, readFileSync } from 'node:fs';
import { convert } from './icbmodel.mjs';

const words = ['a','b','c','alpha','beta','x'];
function rnd(n){ return Math.floor(Math.random()*n); }
function pick(a){ return a[rnd(a.length)]; }

function makeDoc(){
  const nLines = 1 + rnd(7);
  const lines = [];
  for (let i=0;i<nLines;i++){
    const kind = rnd(10);
    if (kind < 3) lines.push('');                                   // blank
    else if (kind < 5) lines.push(pick(words));                      // plain
    else if (kind < 6) lines.push(' '.repeat(1+rnd(3)) + pick(words));// 1-3 space
    else if (kind < 8) lines.push('    ' + pick(words));             // 4 space
    else if (kind < 9) lines.push(' '.repeat(4+rnd(4)) + pick(words));// 4-7
    else lines.push('\t'.repeat(1+rnd(2)) + pick(words));            // tabs
  }
  let s = lines.join('\n');
  if (rnd(3)===0) s += '\n';
  if (rnd(6)===0) s += '\n';
  return s;
}

const N = parseInt(process.argv[2]||'300',10);
const cases = [];
const seen = new Set();
while (cases.length < N){
  const d = makeDoc();
  if (!d.trim()) continue;
  if (seen.has(d)) continue;
  seen.add(d); cases.push(d);
}
writeFileSync('/tmp/icb-fuzz.json', JSON.stringify(cases));
const r = spawnSync('node', ['/workspace/tools/probe.mjs','--file','/tmp/icb-fuzz.json'], {encoding:'utf8', maxBuffer:1<<28});
const res = JSON.parse(r.stdout);
let bad = 0;
for (const {input, output} of res){
  const mine = convert(input);
  if (mine !== output){
    bad++;
    if (bad <= 15){
      console.log('MISMATCH');
      console.log('  in   ' + JSON.stringify(input));
      console.log('  exe  ' + JSON.stringify(output));
      console.log('  mine ' + JSON.stringify(mine));
    }
  }
}
console.log(`total=${res.length} mismatches=${bad}`);

import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
import { convert } from './icbmodel.mjs';

const conts = ['a','b&c','x<y>z','q"1\'2','日本語','😀e','A\tB','p\\q','&amp;','#h','*e*','- l','[r]: u','', 'z   ', 'w\t'];
const rnd=(n)=>Math.floor(Math.random()*n);
const pick=(a)=>a[rnd(a.length)];

function line(){
  const k=rnd(14);
  if(k<2) return '';                                     // blank
  if(k<3) return ' '.repeat(1+rnd(9));                   // space-only line
  if(k<4) return '\t'.repeat(1+rnd(3));                  // tab-only line
  if(k<5) return ' '.repeat(rnd(4))+'\t'.repeat(1+rnd(2));// mixed ws-only
  if(k<6) return ' ';                               // nbsp-only (survives normalize)
  if(k<7) return '\t'+pick(conts);                       // tab indent
  if(k<8) return '\t\t'+pick(conts);
  if(k<9) return ' '.repeat(4+rnd(6))+pick(conts);       // 4-9 spaces
  if(k<10) return '  \t'+pick(conts);
  return '    '+pick(conts);
}
function makeDoc(){
  const n=1+rnd(8);
  const ls=[' '.repeat(4+rnd(3))+pick(conts.filter(c=>c!==''))];
  for(let i=0;i<n;i++) ls.push(line());
  let s=ls.join('\n');
  const t=rnd(4); if(t===0)s+='\n'; if(t===1)s+='\n\n'; if(t===2)s+='   \n';
  return s;
}
const N=parseInt(process.argv[2]||'250',10);
const cases=[]; const seen=new Set();
while(cases.length<N){ const d=makeDoc(); if(!d.trim())continue; if(seen.has(d))continue; seen.add(d); cases.push(d); }
writeFileSync('/tmp/icb-fuzz2.json', JSON.stringify(cases));
const r=spawnSync('node',['/workspace/tools/probe.mjs','--file','/tmp/icb-fuzz2.json'],{encoding:'utf8',maxBuffer:1<<28});
if(r.status!==0){ console.log('EXE ERR', r.stderr.slice(0,500)); process.exit(1); }
const res=JSON.parse(r.stdout);
let bad=0;
for(const {input,output} of res){
  const mine=convert(input);
  if(mine!==output){ bad++; if(bad<=15){ console.log('MISMATCH'); console.log('  in   '+JSON.stringify(input)); console.log('  exe  '+JSON.stringify(output)); console.log('  mine '+JSON.stringify(mine)); } }
}
console.log(`total=${res.length} mismatches=${bad}`);
